def F(page, x0, y0, x1, y1, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}

def L(title, pages, objectives, intro, summary, points, application, board):
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": application[0], "a": application[1]}, "board": board}

def S(h, lines=None, table=None, fig=None):
    d = {"h": h, "lines": lines or []}
    if table: d["table"] = table
    if fig: d["fig"] = fig
    return d

